/* From Uiverse.io by gharsh11032000 - Tags: button, border, hover effect */
.__UIV_SCOPE__ .button {
  border-radius: 8px;
  border: 1px solid transparent;
  padding: 0.6em 1.2em;
  font-size: 1em;
  font-weight: 500;
  font-family: inherit;
  background-color: #1a1a1a;
  cursor: pointer;
  color: white;
  transition: border-color 0.25s;
}

.__UIV_SCOPE__ .button:hover {
  border-color: #646cff;
}

.__UIV_SCOPE__ .button:focus,
.__UIV_SCOPE__ .button:focus-visible {
  outline: 4px auto -webkit-focus-ring-color;
}
